import type { APIRoute, GetStaticPaths } from "astro";

// The JSON Schemas of signed post metadata, generated by `pnpm schemas` in the
// SDK and served byte for byte. Every published post links to its schema here,
// so a published path must keep serving the same file.
const schemas = import.meta.glob<string>(
  "../../../../../packages/sdk/jsonschemas/posts/*.json",
  { eager: true, query: "?raw", import: "default" },
);

export const getStaticPaths = (() =>
  Object.entries(schemas).map(([file, schema]) => ({
    params: { path: file.slice(file.indexOf("/posts/") + 1) },
    props: { schema },
  }))) satisfies GetStaticPaths;

export const GET: APIRoute<{ schema: string }> = ({ props }) =>
  new Response(props.schema);
